class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        north = south = east = west = 0
        ans = 0

        for i, c in enumerate(s):
            if c == 'N':
                north += 1
            elif c == 'S':
                south += 1
            elif c == 'E':
                east += 1
            else:
                west += 1

            length = i + 1
            dist = abs(north - south) + abs(east - west)
            ans = max(ans, min(length, dist + 2 * k))

        return ans
